/**
 * Bank statement posting rules — keyword catalog for accounting classification.
 * SSOT mã CP / ĐK: Master `expense_items.csv` + `posting_reason_rules.csv`
 *   (parity REVA `bank-statement-expense-ssot.mjs` · chi-phi-grepkey-seed.md)
 * Skill: /summary-sao-ke-ngan-hang
 *
 * Form import: costCode · postingReasonCode · companyCode (cấm Guid) ·
 * customer match STK (`bankAccountCode`) rồi tên.
 */

export type PostingCategoryKind =
  | 'payment'
  | 'expense'
  | 'transfer'
  | 'income'
  | 'fee'
  | 'unknown';

export interface PostingCategoryEntry {
  code: string;
  label: string;
  kind: PostingCategoryKind;
  /** ĐK exclusive primary (+ optional secondary tay). */
  postingCodes: string[];
  keywords?: RegExp[];
  descriptionOnlyKeywords?: RegExp[];
  supplierKeywords?: RegExp[];
  priority?: number;
  /**
   * `false` = không bắt buộc ĐT (ShowOnImportFilter).
   * Default / omit = true → thiếu ĐT thì Đối soát / map lô.
   */
  requiresCounterparty?: boolean;
}

export function normPostingText(s: string): string {
  return String(s ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'D')
    .toLowerCase();
}

