import React from 'react';
import {
  getActiveCompanyCode,
  getAuthUser,
  getCompanyBranding,
} from '@linm-soft-org/linm-web-common-components';

export interface ImpCompanyBadgeProps {
  /** `companyCode` header IMP. */
  voucherCompanyCode?: string | null;
  testId?: string;
}

/**
 * Badge ĐVCS khi xem IMP cross-company (GAP-IMP-XC-03).
 * Hiện khi user đa đơn vị và `voucher.companyCode ≠ activeCompanyCode`.
 */
export const ImpCompanyBadge: React.FC<ImpCompanyBadgeProps> = ({
  voucherCompanyCode,
  testId = 'kt-import-sao-ke-company-badge',
}) => {
  const activeCompanyCode = (getActiveCompanyCode() || '').trim();
  const voucherCode = (voucherCompanyCode || '').trim();
  const authUser = getAuthUser();
  const userHasMultipleCompanies = Boolean(
    authUser?.canViewAllCompanies
    || authUser?.role === 'admin'
    || (authUser?.allowedCompanyCodes?.length ?? 0) > 0,
  );

  const isCrossCompany = Boolean(
    voucherCode
    && activeCompanyCode
    && voucherCode.toUpperCase() !== activeCompanyCode.toUpperCase(),
  );

  if (!userHasMultipleCompanies || !isCrossCompany) return null;

  const companyBranding = getCompanyBranding();
  const badgeLabel = companyBranding?.code === voucherCode && companyBranding?.shortName
    ? companyBranding.shortName
    : voucherCode;

  return (
    <span
      data-testid={testId}
      style={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 4,
        padding: '2px 8px',
        borderRadius: 4,
        fontSize: 12,
        fontWeight: 600,
        background: '#e0f2fe',
        color: '#0369a1',
        border: '1px solid #7dd3fc',
        whiteSpace: 'nowrap',
      }}
      title={`Đơn vị hoạch toán: ${voucherCode} (đang làm việc: ${activeCompanyCode})`}
    >
      <svg
        width="14"
        height="14"
        viewBox="0 0 24 24"
        fill="none"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        style={{ marginRight: 2 }}
        aria-hidden
      >
        <rect x="2" y="3" width="20" height="14" rx="2" ry="2" />
        <line x1="8" y1="21" x2="16" y2="21" />
        <line x1="12" y1="17" x2="12" y2="21" />
      </svg>
      {badgeLabel}
    </span>
  );
};
